import com.fasterxml.jackson.databind.ObjectMapper;
import java.util.Map;

String x = "{ \"nombre\":\"Juan\", \"edad\":30, \"ciudad\":\"Madrid\" }";
ObjectMapper mapper = new ObjectMapper();

// Java requiere librerías como Jackson o Gson
Map<String, Object> y = mapper.readValue(x, Map.class);
System.out.println(y.get("edad"));

import com.fasterxml.jackson.databind.ObjectMapper;
import java.util.HashMap;

HashMap<String, Object> x = new HashMap<>();
x.put("nombre", "Juan");
x.put("edad", 30);

ObjectMapper mapper = new ObjectMapper();
String y = mapper.writeValueAsString(x);
System.out.println(y);

import com.fasterxml.jackson.databind.ObjectMapper;

// En Jackson, se habilita PrettyPrint:
ObjectMapper mapper = new ObjectMapper();
String y = mapper.writerWithDefaultPrettyPrinter().writeValueAsString(x);
System.out.println(y);
